{"implementation":"def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    prev = None
    for _ in range(max_rounds):
        for p in passes:
            text = text.replace(p['old'], p['new'])
        if text == prev:
            break
        prev = text
    return text"}
